import {createEnvironment} from './environment.js';
import {closeDaybook} from './immersive.js';
import {connectCloud,newId} from './cloud.js';
const cloud=await connectCloud();
import {createScene} from './scene.js?v=9';
import {createModelView} from './model-room.js?v=3';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const names=['小禾','阿远'],planets=['慢慢星','晚风星'],cities=['未设置所在地','未设置所在地'];
const foods={milk:['草莓牛奶','🥛'],pudding:['焦糖布丁','🍮'],cookie:['黄油曲奇','🍪'],rice:['米饭','🍚'],egg:['鸡蛋','🥚'],tomato:['番茄','🍅']};
const recipes={omelet:{name:'番茄蛋包饭',icon:'🍛',needs:{rice:1,egg:1,tomato:1}},toast:{name:'暖心蒸蛋',icon:'🍲',needs:{egg:1}},milk:{name:'热草莓牛奶',icon:'🥛',needs:{milk:1}}};
const weatherData={sun:['☀','24°','晴朗，有一点微风','晴'],rain:['☂','21°','小雨，适合窝在家里','雨'],snow:['❄','−1°','雪花轻轻落下','雪'],night:['☾','18°','夜色温柔，灯为你留着','夜']};
const uid=newId,key='our-little-skies-v1';
function today(){let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function initial(){return {version:1,actor:0,worlds:[0,1].map(i=>({weather:i?'rain':'sun',deco:false,fridge:['milk','pudding','rice','egg','tomato'].map(food=>({id:uid(),food,qty:3})),meals:[]})),bags:[{cookie:3,pudding:2,milk:2},{cookie:3,pudding:2,milk:2}],events:[],notes:[],favorites:[[],[]]}}
let state;if(cloud){state=cloud.state}else try{let raw=JSON.parse(localStorage.getItem(key));state=raw?.version===1&&raw.worlds?.length===2&&Array.isArray(raw.events)&&Array.isArray(raw.notes)&&raw.bags&&raw.favorites?raw:initial()}catch{state=initial()}
let actor=state.actor===1?1:0,world=actor,inside=false,visual=null,currentPanel='',journalTab='personal',recipe='omelet',recipient='self',toastTimer,game=null;
let environment=null;
let modelView=null,selectedFood=null,selectedMeal=null,fridgePage=0,cookStage=0,mealDraft='';
function dropModel(){const old=modelView;modelView=null;old?.dispose()}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=s=>new Date(s).toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function save(){state.actor=actor;if(cloud){cloud.save();recent();return}try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('浏览器无法保存，本次记录暂时保留在页面中。')}recent()}
function weatherStamp(){if(environment)return environment.stamp();return state.worlds.map((w,i)=>cities[i]+' · '+weatherData[w.weather][3]).join(' / ')}
function record(title,body,opts={}){const e={id:uid(),title,body,actor,world,target:null,shared:false,pending:false,kind:'life',created:Date.now(),weather:weatherStamp(),steps:[],comments:[],...opts};state.events.unshift(e);save();return e}
function visible(e,shared=false){return shared?e.shared&&!e.pending:e.actor===actor||(!e.pending&&(e.target===actor||e.shared))}
function discover(items){let n=0;for(const item of items){const e=state.events.find(e=>e.id===item.event);if(e?.pending&&e.target===actor){e.pending=false;e.steps.push({text:names[actor]+'发现了这份心意。',at:Date.now()});n++}}if(n){save();toast('发现了 '+n+' 份心意，已经写进手账。')}}
function recent(){if(!$('#recent-events'))return;const list=state.events.filter(e=>visible(e)).slice(0,2);$('#recent-events').innerHTML=list.length?list.map(e=>'<div class="recent-item"><span class="recent-dot"></span><span>'+esc(e.title)+'<small>'+time(e.created)+' · '+planets[e.world]+'</small></span></div>').join(''):'<div class="recent-item"><span class="recent-dot"></span><span>今天的故事，等你写下第一笔。<small>做顿饭，或去对方家里坐坐</small></span></div>'}
function refresh(){const w=state.worlds[world],v=weatherData[w.weather];$('#place').textContent=planets[world]+' · '+cities[world];$('#weather-icon').textContent=v[0];$('#temperature').textContent=v[1];$('#weather-description').textContent=v[2];$('#owner-label').textContent=inside?names[world]+'的小屋 · 欢迎来坐坐':'林间的小小日常';$('#scene-heading').textContent=inside?(world===actor?'回家，把日子过暖。':'来你家，待一会儿。'):(world===actor?'今天，也好好生活。':'看看你那边的天空。');$('#scene-subtitle').textContent=inside?'点一点家具，发现生活里的小事。':world===actor?'风经过树梢。家里还有一点小惊喜。':'带来的心意，可以放进冰箱或留在餐桌上。';$('#enter-home').textContent=inside?'回到院子 ↗':'走进小屋 ↗';$('#scene-hint').textContent=inside?'点击家具，走过去互动':'WASD / 方向键行走 · 拖动观察';$('#identity-text').textContent=names[actor]+'的视角';$('.avatar').textContent=names[actor][0];$('#partner-peek').innerHTML='<span class="tiny-orbit">◒</span><span><small>'+planets[1-world]+' · '+cities[1-world]+'</small><b>去'+(world===actor?'对方':'自己')+'的星球坐坐</b></span><span>↗</span>';$$('[data-world]').forEach(b=>b.classList.toggle('active',world===(b.dataset.world==='0'?actor:1-actor)));$$('[data-weather]').forEach(b=>b.classList.toggle('active',b.dataset.weather===w.weather));$$('[data-nav]').forEach(b=>b.classList.toggle('selected',b.dataset.nav===(inside?'home':'planet')));visual?.world(world,w.deco);visual?.actor?.(actor);if(!environment)visual?.weather(w.weather);visual?.food(w.meals.length>0);visual?.camp?.(!!w.camp);$('#date-stamp').textContent=new Date().toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'});recent();environment?.paint()}
function close(){dropModel();$('#panel').close();currentPanel=''}
function enter(){endOutdoor();inside=true;visual?.enter(true);refresh()}
function go(i){if(cloud&&i!==actor&&!cloud.paired){settings();return toast('先用邀请码连接对方，再去做客。')}endOutdoor();world=i;inside=false;visual?.enter(false);close();refresh();toast(world===actor?'回到自己的小星球。':'抵达'+planets[world]+'，看看这里的天空。')}
function modal(id,kicker,title,html){closeDaybook();dropModel();currentPanel=id;$('#panel').classList.toggle('model-panel',['fridge','cook','table'].includes(id));$('#panel-kicker').textContent=kicker;$('#panel-title').textContent=title;$('#panel-body').innerHTML=html;if(!$('#panel').open)$('#panel').showModal()}
const btn=(action,text,primary=false,extra='')=>'<button class="pill '+(primary?'primary':'')+'" data-do="'+action+'" '+extra+'>'+text+'</button>';
function fridge(){enter();discover(state.worlds[world].fridge);const all=state.worlds[world].fridge;fridgePage=Math.max(0,Math.min(fridgePage,Math.ceil(all.length/9)-1));const items=all.slice(fridgePage*9,fridgePage*9+9);if(!items.some(i=>i.id===selectedFood))selectedFood=items[0]?.id||null;
modal('fridge','SOMETHING SWEET',names[world]+'的冰箱','<p class="subtle">点选架上的食物，再拿起来吃或装进随身包。拖动可以换个角度看。</p><div id="model-stage" aria-label="可点选的三维冰箱"></div><div class="model-picks">'+items.map(i=>'<button data-do="select-food" data-id="'+i.id+'">'+foods[i.food][0]+' ×'+i.qty+'</button>').join('')+'</div><div id="model-selection"></div><div class="inline-actions">'+btn('bag','从随身包放入')+(world===actor?btn('restock','补充食材'):'')+(all.length>9?btn('fridge-prev','上一层')+'<span class="subtle">'+(fridgePage+1)+' / '+Math.ceil(all.length/9)+'</span>'+btn('fridge-next','下一层'):'')+'</div>');
modelView=createModelView($('#model-stage'),{mode:'fridge',items:items.map(i=>({...i,gift:!!i.event})),onSelect:i=>selectFood(i.id)});selectFood(selectedFood)}
function selectFood(id){selectedFood=id;const i=state.worlds[world].fridge.find(i=>i.id===id);if(!i){$('#model-selection').innerHTML='<p class="subtle">冰箱空了，放一点喜欢的东西进来吧。</p>';return}const e=findRecord(i.event),reserved=e?.pending&&e.target!==actor;modelView?.select(id);$$('[data-do="select-food"]').forEach(b=>b.classList.toggle('active',b.dataset.id===id));$('#model-selection').innerHTML='<div class="selected-food"><div><b>'+foods[i.food][0]+'</b><small>'+(i.event?'来自'+names[e?.actor??world]+'的心意':'还剩 '+i.qty+' 份')+'</small></div><div>'+(reserved?'<span class="subtle">留给对方，等待发现</span>':btn('eat-model','拿起来吃',true,'data-id="'+id+'"'))+(!i.event&&world===actor?' '+btn('pack-model','装进随身包',false,'data-id="'+id+'"'):'')+'</div></div>'}


function bag(){modal('bag','A LITTLE SOMETHING','随身带着的心意','<p class="subtle">现在位于'+names[world]+'的'+planets[world]+'。放入对方冰箱，就为对方留下一份零食。</p><div class="grid" style="margin-top:18px">'+(Object.entries(state.bags[actor]).filter(([f,q])=>q>0&&foods[f]).map(([f,q])=>'<div class="item"><span class="count">× '+q+'</span><span class="emoji">'+foods[f][1]+'</span><b>'+foods[f][0]+'</b><small>'+(world===actor?'放回自己的冰箱':'给'+names[world]+'留一份')+'</small>'+btn('deposit','放进冰箱',true,'data-food="'+f+'"')+'</div>').join('')||'<div class="empty">包里暂时空了。</div>')+'</div><div class="form-actions">'+btn('snacks','补充三种零食')+'</div><p class="subtle" style="margin-top:12px">原型里的基础食材和零食可免费补充。</p>')}
function amount(f){return state.worlds[world].fridge.filter(i=>i.food===f&&!i.event).reduce((n,i)=>n+i.qty,0)}
function enough(){return Object.entries(recipes[recipe].needs).every(([f,q])=>amount(f)>=q)}
function kitchen(){enter();const r=recipes[recipe],labels=['把食材备好','处理食材','下锅慢慢加热','装盘完成'];modal('cook','MADE WITH CARE','在厨房，为你做一顿饭','<div class="chips">'+Object.entries(recipes).map(([id,r])=>'<button data-do="recipe" data-id="'+id+'" class="'+(id===recipe?'active':'')+'">'+r.name+'</button>').join('')+'</div><div id="model-stage" class="kitchen-stage" aria-label="可以操作的三维灶台"></div><div class="cooking-progress">'+labels.map((x,i)=>'<span class="'+(i===cookStage?'active':'')+'">'+(i+1)+' · '+x+'</span>').join('')+'</div><p class="subtle">'+Object.entries(r.needs).map(([f,q])=>foods[f][0]+' '+amount(f)+'/'+q).join(' · ')+'。点击模型或下方按钮，完成备料、下锅和装盘。</p><div class="chips">'+[['self','给自己'],['partner','留给'+names[1-actor]],['together','一起做 · 演示']].filter(([id])=>!cloud||id!=='together').map(([id,n])=>'<button data-do="recipient" data-id="'+id+'" class="'+(recipient===id?'active':'')+'">'+n+'</button>').join('')+'</div><input id="meal-message" maxlength="120" aria-label="留给这顿饭的话" placeholder="回来记得吃，今天也辛苦了。" value="'+esc(mealDraft)+'"><div class="form-actions">'+(!enough()?btn('restock','补充基础食材'):'')+(cookStage<3?btn('cook-step',['放到案板上','放进锅里','盛到盘子里'][cookStage],true,enough()?'':'disabled'):btn('cook-done','摆上餐桌',true,enough()?'':'disabled'))+'</div>');
modelView=createModelView($('#model-stage'),{mode:'cook',recipe,needs:r.needs,stage:cookStage,onStep:advanceCooking});$('#meal-message').oninput=e=>mealDraft=e.target.value}
function advanceCooking(){if(!enough())return toast('食材还不够，先补充一点。');if(cookStage>=3)return;mealDraft=$('#meal-message')?.value||mealDraft;cookStage++;modelView?.step(cookStage);$$('.cooking-progress span').forEach((e,i)=>e.classList.toggle('active',i===cookStage));const b=$('[data-do="cook-step"]');if(b){b.textContent=cookStage===3?'摆上餐桌':['放到案板上','放进锅里','盛到盘子里'][cookStage];if(cookStage===3)b.dataset.do='cook-done'}toast(['','食材放到案板上了。','食材正在锅里慢慢加热。','装盘好了，可以给这顿饭留句话。'][cookStage])}


function cook(){if(cloud&&recipient!=='self'&&!cloud.paired)return toast('请先与对方配对。');if(cloud&&recipient==='together')return toast('实时共同做饭还没有开放，可以先给对方留饭。');if(!enough())return;const r=recipes[recipe],target=recipient==='self'?actor:1-actor,together=recipient==='together',message=$('#meal-message')?.value.trim()||'';for(const [f,q]of Object.entries(r.needs)){let n=q;for(const i of state.worlds[world].fridge){if(i.food===f&&!i.event){const take=Math.min(i.qty,n);i.qty-=take;n-=take}}}state.worlds[world].fridge=state.worlds[world].fridge.filter(i=>i.qty>0);const e=record(together?'我们一起做了'+r.name:names[actor]+'为'+(target===actor?'自己':names[target])+'做了'+r.name,message||'一顿热乎乎的饭，慢慢吃。',{target,shared:target!==actor,pending:target!==actor&&!together});state.worlds[world].meals.push({id:uid(),recipe,owner:target,event:e.id,together});cookStage=0;mealDraft='';save();refresh();table();toast('饭做好了，已经摆上餐桌，也记进了手账。')}
function table(){enter();discover(state.worlds[world].meals);const items=state.worlds[world].meals;if(!items.some(i=>i.id===selectedMeal))selectedMeal=items[0]?.id||null;modal('table','AT THE TABLE','餐桌上的小小心意','<p class="subtle">点选桌上的饭。留给对方的饭盒，会等对方回来再打开。</p><div id="model-stage" class="table-stage" aria-label="可点选饭菜的三维餐桌"></div><div class="model-picks">'+items.map(i=>'<button data-do="select-meal" data-id="'+i.id+'">'+recipes[i.recipe].name+' · '+(i.together?'一起做的':names[i.owner])+'</button>').join('')+'</div><div id="model-selection"></div><div class="form-actions">'+btn('cook','再做一顿饭')+'</div>');
modelView=createModelView($('#model-stage'),{mode:'table',items:items.map(i=>({...i,locked:i.owner!==actor&&!i.together})),onSelect:i=>selectMeal(i.id)});selectMeal(selectedMeal)}
function selectMeal(id){selectedMeal=id;const m=state.worlds[world].meals.find(i=>i.id===id);if(!m){$('#model-selection').innerHTML='<p class="subtle">桌上还没有饭菜。去厨房做一顿吧。</p>';return}modelView?.select(id);const e=findRecord(m.event);$('#model-selection').innerHTML='<div class="selected-food"><div><b>'+recipes[m.recipe].name+'</b><small>'+esc(e?.body||'慢慢吃，好好享受。')+'</small></div>'+(m.owner===actor||m.together?btn('eat-meal-model','吃这份饭',true,'data-id="'+id+'"'):'<span class="subtle">保温中 · 留给'+names[m.owner]+'</span>')+'</div>'}


function listRecords(){if(journalTab==='dates')return state.notes.filter(n=>n.kind==='anniversary'&&(n.actor===actor||n.shared)).sort((a,b)=>a.date.localeCompare(b.date));return [...state.events.filter(e=>visible(e,journalTab==='shared')),...state.notes.filter(n=>journalTab==='shared'?n.shared:n.actor===actor||n.shared)].filter(e=>journalTab!=='favorites'||state.favorites[actor].includes(e.id)).sort((a,b)=>b.created-a.created)}
function card(e){return '<article class="memory"><div class="meta"><span>'+(e.kind==='anniversary'?'◷ 纪念日':e.shared?'♡ 共同记忆':'✎ 个人生活')+(e.pending?' · 等对方发现':'')+'</span><span>'+esc(e.date||time(e.created))+'</span></div><h3>'+esc(e.title)+'</h3><p>'+esc(e.body)+'</p>'+(e.steps||[]).map(s=>'<div class="reply">'+esc(s.text)+' <span class="subtle">'+time(s.at)+'</span></div>').join('')+(e.comments||[]).map(c=>'<div class="reply"><b>'+names[c.actor]+'</b>：'+esc(c.text)+'</div>').join('')+'<div class="foot">'+planets[e.world]+' · '+esc(e.weather||'手动记录')+(e.repeat?' · 每年纪念':'')+'</div><div class="inline-actions"><button data-do="favorite" data-id="'+e.id+'">'+(state.favorites[actor].includes(e.id)?'★ 已珍藏':'☆ 珍藏')+'</button><button data-do="reply" data-id="'+e.id+'">添一句话</button>'+(e.actor===actor&&!e.shared?'<button data-do="share" data-id="'+e.id+'">放入共同回忆册</button>':'')+(e.actor===actor?'<button data-do="delete" data-id="'+e.id+'">删除</button>':'')+'</div></article>'}
function journal(tab=journalTab){journalTab=tab;const list=listRecords();modal('journal','OUR LITTLE MEMORIES',tab==='shared'?'我们的共同回忆册':names[actor]+'的生活手账','<div class="cover-mini"><img src="journal-cover.png" alt="两间小屋与一颗小星球的手账封面"><p>为自己、为你、和你一起。<br><span class="subtle">生活足迹自动收好，心情由你亲手写。</span></p></div><div class="chips">'+[['personal','我的足迹'],['shared','共同回忆'],['dates','纪念日'],['favorites','珍藏']].map(([id,n])=>'<button data-do="journal-tab" data-id="'+id+'" class="'+(id===tab?'active':'')+'">'+n+'</button>').join('')+'</div><div class="inline-actions">'+btn('write','＋ 写一页',true)+btn('anniversary','＋ 纪念日')+btn('export','导出本页记录')+'</div><div id="memories">'+(list.map(card).join('')||'<div class="empty" style="margin-top:18px"><img src="journal-cover.png" alt="星球回忆插画">这里还没有记录。去做一件小事，或亲手写一页吧。</div>')+'</div>')}
function write(kind='memory'){modal('write','A PAGE FOR TODAY',kind==='anniversary'?'把重要的日子记下来':'写下此刻的心情','<form id="note-form"><input type="hidden" name="kind" value="'+kind+'"><div class="form-row"><label for="note-title">'+(kind==='anniversary'?'纪念日名称':'这一页的名字')+'</label><input id="note-title" name="title" required maxlength="80" placeholder="'+(kind==='anniversary'?'第一次见面的日子':'今天的一点小幸福')+'"></div><div class="form-row"><label for="note-body">想留下的话</label><textarea id="note-body" name="body" maxlength="2000" placeholder="为自己做了什么？为对方准备了什么？一起经历了什么？"></textarea></div><div class="grid"><div class="form-row"><label for="note-date">日期</label><input type="date" id="note-date" name="date" value="'+today()+'" required></div><div class="form-row"><label for="note-visibility">收在哪里</label><select id="note-visibility" name="visibility"><option value="private">自己的私人手账</option><option value="shared" '+(journalTab==='shared'?'selected':'')+'>两个人的共同回忆册</option></select></div></div>'+(kind==='anniversary'?'<label class="subtle"><input name="repeat" type="checkbox" checked style="width:auto"> 每年纪念这一天（本版仅标记，不发送通知）</label>':'')+'<div class="form-actions"><button type="submit" class="pill primary">收进手账</button></div></form>')}
function decorate(){modal('decorate','MAKE IT YOURS','让家，多一点你的样子','<p class="subtle">'+(world===actor?'给院子放一盆小花，装扮会留在自己的星球上。':'正在对方家做客，装扮需要回到自己的星球。')+'</p><div class="item" style="margin-top:18px"><span class="emoji">🌼</span><b>窗前的金色小花</b><small>一小盆，也能让家变温暖。</small>'+(world===actor?btn('flower',state.worlds[world].deco?'收起花盆':'摆进院子',true):btn('go-own','回自己的星球',true))+'</div>')}
let audio=null,timer=null,musicOn=false;
function stopMusic(){clearInterval(timer);audio?.close();audio=null;musicOn=false}
function playMusic(){if(musicOn){stopMusic();music();return}try{audio=new(window.AudioContext||window.webkitAudioContext)();audio.resume();musicOn=true;const tones=[261.63,329.63,392,523.25,440,392,329.63,293.66];let n=0;const tick=()=>{if(!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=tones[n++%tones.length];g.gain.setValueAtTime(0,audio.currentTime);g.gain.linearRampToValueAtTime(.05,audio.currentTime+.03);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+1.8);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+2)};tick();timer=setInterval(tick,700);music()}catch{toast('当前浏览器暂时不能播放声音。')}}
function music(){enter();modal('music','A QUIET AFTERNOON','给房间放一点音乐','<div class="item" style="text-align:center"><span class="emoji">♫</span><b>窗边的小小旋律</b><small>一段轻轻循环的合成音符</small>'+(musicOn?'<div class="music-bars"><i></i><i></i><i></i><i></i><i></i></div>':'')+btn('play-music',musicOn?'暂停音乐':'播放音乐',true)+'</div><p class="subtle" style="margin-top:15px">音乐只在当前设备播放，可以随时暂停。</p>')}
function newGame(){let cards=['🍓','🌼','🍮','🌙','🍓','🌼','🍮','🌙'];for(let i=cards.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]]}game={cards,open:[],matched:[],moves:0,locked:false,done:false}}
function games(){enter();if(!game)newGame();modal('games','PLAY A LITTLE','茶几上的翻牌游戏','<p class="subtle">找出四组相同的小物件。</p><p class="subtle" style="margin:12px 0">已尝试 '+game.moves+' 次 · 找到 '+game.matched.length/2+'/4 组</p><div class="match-grid">'+game.cards.map((c,i)=>'<button data-do="flip" data-id="'+i+'" aria-label="第 '+(i+1)+' 张牌" class="'+(game.matched.includes(i)?'matched':'')+'" '+(game.locked||game.matched.includes(i)?'disabled':'')+'>'+(game.open.includes(i)||game.matched.includes(i)?c:'✳')+'</button>').join('')+'</div><div class="form-actions">'+btn('new-game','重新洗牌')+'</div>')}
function settings(){if(cloud)return cloudSettings();modal('settings','PLAYABLE PROTOTYPE','在两个人的生活间切换','<p class="subtle">当前是'+names[actor]+'的视角。切换角色后，可以发现另一位留下的饭和零食，查看各自的手账。</p><div class="chips">'+names.map((n,i)=>'<button data-do="switch-actor" data-id="'+i+'" class="'+(i===actor?'active':'')+'">'+n+' · '+planets[i]+'</button>').join('')+'</div><div class="preview-info">这是单设备交互原型：两位角色、城市与天气为演示，尚未接入真实定位、天气接口、账号或跨设备联机。记录保存在当前浏览器；私人手账的分隔用于演示，不构成真实账号权限。音乐是本地生成的简短旋律。</div><div class="form-actions">'+btn('export-all','导出当前角色全部手账')+'</div>')}
function findRecord(id){return state.events.find(e=>e.id===id)||state.notes.find(e=>e.id===id)}
function reply(id){const e=findRecord(id);if(!e)return;modal('reply','ADD YOUR WORDS','在回忆旁，添一句话','<p class="subtle">'+esc(e.title)+'</p><form id="reply-form" data-id="'+id+'"><div class="form-row"><label for="reply-text">'+names[actor]+'想说</label><textarea id="reply-text" name="text" required maxlength="500"></textarea></div><div class="form-actions"><button type="submit" class="pill primary">留下这句话</button></div></form>')}
function exportRecords(all=false){const list=all?[...state.events.filter(e=>visible(e)),...state.notes.filter(e=>e.actor===actor||e.shared)]:listRecords();const text='# '+names[actor]+'的生活手账\n\n'+list.map(e=>'## '+e.title+'\n'+(e.date||time(e.created))+' · '+planets[e.world]+'\n\n'+e.body+'\n'+(e.steps||[]).map(s=>s.text).join('\n')+'\n'+(e.comments||[]).map(c=>names[c.actor]+'：'+c.text).join('\n')+'\n').join('\n---\n\n');const u=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=names[actor]+'的生活手账-'+today()+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);toast('手账已导出为文字文件。')}
function roomMenu(){enter();modal('room','MAKE YOURSELF AT HOME',names[world]+'的小屋','<p class="subtle">一层做饭、听音乐；沿楼梯上二层，在卧室休息或写手账。也可以直接点小屋里的家具。</p><div class="room-list" style="margin-top:20px">'+[['stairs','↟','上下楼'],['bed','☾','二层卧室'],['fridge','♧','冰箱'],['cook','♨','厨房'],['table','◯','餐桌'],['journal','▤','书桌手账'],['music','♫','音乐'],['games','✳','小游戏']].map(([a,i,t])=>'<button data-do="'+a+'"><span>'+i+'</span><small>'+t+'</small></button>').join('')+'</div>')}
function act(a){if(a==='stairs'){visual?.climb();return}if(a==='bed'){bedroom();return}if(a==='puppy'){showPet();return}if(a.startsWith('pet-')){petCompleted(a);return}if(a==='activity-ended'){endOutdoor();return}if(a==='camp'){campSite();return}if(a==='sit'&&!inside){readBench();return}if(a==='walk-complete'){record(names[actor]+'绕着'+planets[world]+'散步了一圈','走过树林、菜园和小屋，又回到熟悉的地方。',{target:world,shared:world!==actor});toast('散步一圈的记忆，已经收进手账。');return}if(a==='home'){enter();return}({fridge,cook:kitchen,table,journal,bag,decorate,music,games,settings,room:roomMenu})[a]?.();if(a==='sit'){modal('sit','TAKE YOUR TIME','坐一会儿，也很好','<p class="subtle">这里是'+weatherData[state.worlds[world].weather][2]+'。想做什么，就慢慢来。</p><div class="room-list" style="margin-top:20px"><button data-do="music"><span>♫</span><small>听段音乐</small></button><button data-do="games"><span>✳</span><small>玩个小游戏</small></button><button data-do="write"><span>▤</span><small>写一页手账</small></button></div>')}if(a==='garden'){record(names[actor]+'给'+(world===actor?'自己的':names[world]+'的')+'花坛浇了水','叶子上留下了亮晶晶的小水珠。',{target:world,shared:world!==actor});toast('花坛喝到水了，这一刻已经记进手账。')}if(a==='pet')toast('小兔子抬起头，轻轻蹭了蹭你的手。')}
const handlers={fridge,bag,cook:kitchen,table,music,games,write:()=>write(),anniversary:()=>write('anniversary'),'go-own':()=>go(actor),'play-music':playMusic,'cook-done':cook,export:()=>exportRecords(),'export-all':()=>exportRecords(true),snacks(){for(let f of ['milk','cookie','pudding'])state.bags[actor][f]=(state.bags[actor][f]||0)+2;save();bag();toast('已补充三种喜欢的零食。')},deposit(b){let f=b.dataset.food;if(!foods[f]||!(state.bags[actor][f]>0))return;state.bags[actor][f]--;const e=record(names[actor]+'给'+(world===actor?'自己':names[world])+'留了一份'+foods[f][0],'放进冰箱的小心意。',{target:world,shared:world!==actor,pending:world!==actor});state.worlds[world].fridge.push({id:uid(),food:f,qty:1,event:world!==actor?e.id:null});save();bag();toast('已经放进冰箱。')},'eat-fridge'(b){let i=state.worlds[world].fridge.find(i=>i.id===b.dataset.id);if(!i||i.qty<=0)return;let e=state.events.find(e=>e.id===i.event);if(e?.pending&&e.target!==actor)return;i.qty--;if(e)e.steps.push({text:names[actor]+'吃了'+foods[i.food][0]+'。',at:Date.now()});else record(names[actor]+'吃了一份'+foods[i.food][0],'照顾好自己，也是一件值得记下的小事。');state.worlds[world].fridge=state.worlds[world].fridge.filter(i=>i.qty>0);save();fridge();toast('慢慢吃，好好享受这一口。')},pack(b){let i=state.worlds[world].fridge.find(i=>i.id===b.dataset.id);if(!i||world!==actor||i.qty<=0)return;i.qty--;state.bags[actor][i.food]=(state.bags[actor][i.food]||0)+1;state.worlds[world].fridge=state.worlds[world].fridge.filter(i=>i.qty>0);save();fridge();toast('已经装进随身包。')},restock(){if(cloud&&world!==actor)return toast('做客时可以使用已有食材；补充食材请回自己的星球。');for(let f of ['rice','egg','tomato','milk']){let i=state.worlds[world].fridge.find(i=>i.food===f&&!i.event);if(i)i.qty+=3;else state.worlds[world].fridge.push({id:uid(),food:f,qty:3})}save();currentPanel==='cook'?kitchen():fridge();toast('基础食材已经补充好。')},recipe(b){mealDraft=$('#meal-message')?.value||mealDraft;if(recipes[b.dataset.id])recipe=b.dataset.id;cookStage=0;kitchen()},recipient(b){mealDraft=$('#meal-message')?.value||mealDraft;recipient=b.dataset.id;kitchen()},'eat-meal'(b){let m=state.worlds[world].meals.find(m=>m.id===b.dataset.id);if(!m||(m.owner!==actor&&!m.together))return;let e=findRecord(m.event);if(e)e.steps.push({text:names[actor]+'吃掉了'+recipes[m.recipe].name+'，饭盒空了。',at:Date.now()});state.worlds[world].meals=state.worlds[world].meals.filter(i=>i.id!==m.id);save();refresh();table();toast('吃完了，心里也暖了一点。')},'journal-tab'(b){journal(b.dataset.id)},favorite(b){let a=state.favorites[actor];state.favorites[actor]=a.includes(b.dataset.id)?a.filter(i=>i!==b.dataset.id):[...a,b.dataset.id];save();journal()},reply(b){reply(b.dataset.id)},share(b){if(cloud&&!cloud.paired)return toast('请先与对方配对。');let e=findRecord(b.dataset.id);if(e?.actor===actor){e.shared=true;save();journal();toast('已经放入共同回忆册。')}},delete(b){let e=findRecord(b.dataset.id);if(e?.actor!==actor)return;modal('delete','KEEP OR LET GO','删除这条记录？','<p class="subtle">'+esc(e.title)+'<br>删除后将从相关手账中移除。云端版需先吃完关联食物，再删除对应记录。</p><div class="form-actions">'+btn('cancel-delete','保留')+btn('confirm-delete','删除记录',false,'data-id="'+e.id+'"')+'</div>')},'cancel-delete':()=>journal(),'confirm-delete'(b){const id=b.dataset.id;if(cloud&&state.worlds.some(w=>[...w.fridge,...w.meals].some(i=>i.event===id)))return toast('这条记录关联的食物还在，请吃完后再删除。');state.events=state.events.filter(e=>e.id!==id||e.actor!==actor);state.notes=state.notes.filter(e=>e.id!==id||e.actor!==actor);save();journal()},flower(){if(world!==actor)return;let w=state.worlds[world];w.deco=!w.deco;visual?.decorate(w.deco);if(w.deco)record(names[actor]+'在院子里摆了一盆小花','给自己的家，添一点暖黄色。');save();decorate()},'switch-actor'(b){if(cloud)return;let n=Number(b.dataset.id);if(n!==0&&n!==1)return;actor=n;save();go(actor);toast('现在是'+names[actor]+'的视角。')},'new-game'(){newGame();games()},flip(b){if(!game||game.locked)return;let i=Number(b.dataset.id);if(game.open.includes(i)||game.matched.includes(i))return;game.open.push(i);if(game.open.length===2){game.moves++;if(game.cards[game.open[0]]===game.cards[game.open[1]]){game.matched.push(...game.open);game.open=[];if(game.matched.length===8&&!game.done){game.done=true;record(names[actor]+'完成了茶几上的翻牌游戏','用了'+game.moves+'次尝试，找到了四组小物件。');toast('都找到了！这个小成就已经记进手账。')}}else{game.locked=true;let g=game;setTimeout(()=>{if(g!==game)return;game.open=[];game.locked=false;if(currentPanel==='games')games()},850)}}games()}};
$('#panel-body').addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(b&&!b.disabled){if(currentPanel==='room'&&['fridge','cook','table','journal','music','games'].includes(b.dataset.do)){close();visual?.request(b.dataset.do)}else handlers[b.dataset.do]?.(b)}});
$('#panel-body').addEventListener('submit',e=>{e.preventDefault();let d=new FormData(e.target);if(e.target.id==='note-form'){let title=String(d.get('title')||'').trim();if(!title)return;let date=String(d.get('date'));if(cloud&&!cloud.paired&&d.get('visibility')==='shared')return toast('请先配对，或选择私人手账。');state.notes.unshift({id:uid(),actor,world,title,body:String(d.get('body')||'').trim(),date,kind:d.get('kind'),shared:d.get('visibility')==='shared',repeat:d.has('repeat'),created:Date.now(),weather:date===today()?weatherStamp():'',comments:[]});save();journal(d.get('kind')==='anniversary'?'dates':d.get('visibility')==='shared'?'shared':'personal');toast('这一页，已经好好收起来了。')}else if(e.target.id==='reply-form'){let r=findRecord(e.target.dataset.id),text=String(d.get('text')||'').trim();if(r&&text){r.comments??=[];r.comments.push({actor,text,at:Date.now()});save();journal();toast('回忆里，多了你的一句话。')}}});
$('#close-panel').onclick=close;$('#panel').addEventListener('close',()=>{if(!$('#panel').open){dropModel();currentPanel=''}});$('#panel').addEventListener('click',e=>{if(e.target===$('#panel')){let r=$('#panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
$('#enter-home').onclick=()=>{endOutdoor();if(inside){inside=false;visual?.enter(false);refresh()}else visual?.request('home')};$('.brand').onclick=e=>{e.preventDefault();go(actor)};$('#settings').onclick=settings;$('#identity').onclick=settings;$('#partner-peek').onclick=()=>go(1-world);$('#zoom-in').onclick=()=>visual?.zoom(.12);$('#zoom-out').onclick=()=>visual?.zoom(-.12);$('#all-memories').onclick=()=>journal();$$('[data-world]').forEach(b=>b.onclick=()=>go(b.dataset.world==='0'?actor:1-actor));$$('[data-action]').forEach(b=>b.onclick=()=>requestAction(b.dataset.action));$$('[data-weather]').forEach(b=>b.onclick=async()=>{if(cloud&&world!==actor)return toast('天气由这颗星球的主人设置。');if(environment&&!(await environment.manual()))return;state.worlds[world].weather=b.dataset.weather;save();refresh()});$$('[data-nav]').forEach(b=>b.onclick=()=>{let a=b.dataset.nav;if(a==='planet'){endOutdoor();inside=false;visual?.enter(false);refresh()}else if(a==='home'){if(inside)roomMenu();else visual?.request('home');}else act(a)});
try{visual=createScene($('#scene'),act)}catch(e){$('#scene').innerHTML='<div class="error-note">当前设备未能启动 3D 画面。仍可使用右侧和底部按钮体验冰箱、做饭与手账。<br><small>请尝试开启浏览器硬件加速后刷新。</small></div>';console.error('3D unavailable',e)}refresh();
environment=createEnvironment({cloud,context:()=>({world,actor,state,visual}),modal,toast,cities,planets});
if(document.modelContext?.registerTool){for(const tool of [{name:'read_visible_journal',title:'读取当前角色可见的手账',description:'Read journal records visible to the current demo character.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No arguments accepted');return {actor:names[actor],records:state.events.filter(e=>visible(e)).map(e=>({title:e.title,body:e.body,pending:e.pending}))}}},{name:'navigate_planet',title:'前往自己或对方的星球',description:'Navigate within this local prototype; no journal record is created.',inputSchema:{type:'object',properties:{destination:{type:'string',enum:['own','partner']}},required:['destination'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['own','partner'].includes(input.destination)||Object.keys(input).some(k=>k!=='destination'))throw Error('Invalid destination');go(input.destination==='own'?actor:1-actor);return {planet:planets[world],owner:names[world]}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}


function requestAction(a){endOutdoor();if(['fridge','cook','table','music','games'].includes(a)&&visual){close();visual.request(a)}else act(a)}
$('#view-mode').onclick=()=>visual?.toggleView();$('#tour-world').onclick=()=>{if(inside){inside=false;visual?.enter(false);refresh()}visual?.tour()};


const readingPages=['风沿着小路走来，把树叶翻到新的一页。我们不急着赶路，坐在这里，也是在认真生活。','远处的窗户亮起来了。有人在等一锅汤，有人在等一句晚安；长椅替我们留着慢慢说话的时间。','把今天折成一个小小的书角吧。等下一次风吹过，我们还可以回到这里，接着读。'];
let outdoorMode='',readingPage=0,paired=false,readingEvent=null,campEvent=null;
function dock(html){$('#activity-dock').innerHTML=html;$('#activity-dock').hidden=false;$('.scene-wrap').classList.add('engaged')}
function endOutdoor(){if(outdoorMode==='pet'){visual?.stopPet();$('.scene-wrap').classList.remove('pet-active')}visual?.stand();$('#activity-dock').hidden=true;$('.scene-wrap').classList.remove('engaged');outdoorMode='';paired=false;readingEvent=null;campEvent=null}
function readBench(){close();outdoorMode='read';paired=false;readingPage=0;visual?.sit(false,true);readingEvent=record(names[actor]+'在长椅上读了一会儿书','翻开《风路过的地方》，读到树叶与晚风。');renderReading()}
function renderReading(){dock('<div class="dock-heading"><span>▤ '+(paired?'和'+names[1-actor]+'一起读书':'长椅上的一页书')+'</span><button data-outdoor="leave" aria-label="起身离开">×</button></div><p class="book-excerpt">'+readingPages[readingPage]+'</p><div class="dock-actions"><small>'+(readingPage+1)+' / 3 · 原创小短篇</small><button data-outdoor="page">翻一页 ↗</button><button data-outdoor="pair">'+(paired?'自己读一会儿':(cloud?'双人并坐 · 待开放':'邀请对方并坐'))+'</button></div>'+(paired?'<small class="demo-label">双人动作演示 · 尚未联机</small>':''))}
function campSite(){close();outdoorMode='camp';paired=false;renderCamp()}
function renderCamp(){const built=!!state.worlds[world].camp;dock('<div class="dock-heading"><span>△ '+(built?'帐篷搭好了，坐下来吧':'选了一个适合露营的地方')+'</span><button data-outdoor="leave" aria-label="离开营地">×</button></div><p class="subtle">'+(paired?'两个人坐在帐篷前，灯亮着，慢慢聊。':'铺好毯子，留一盏灯。今晚听听风和雨。')+'</p><div class="dock-actions"><button data-outdoor="tent">'+(built?'收起帐篷':'搭起帐篷')+'</button>'+(built?'<button data-outdoor="rest">坐下来露营</button><button data-outdoor="pair">'+(paired?'独自待一会儿':(cloud?'一起露营 · 待开放':'邀请对方一起'))+'</button>':'')+'</div>'+(paired?'<small class="demo-label">双人动作演示 · 尚未联机</small>':''))}
function outdoors(a){endOutdoor();close();if(inside){inside=false;visual?.enter(false);refresh()}visual?.request(a==='read'?'sit':'camp')}
$('#activity-dock').addEventListener('click',e=>{if(e.target.closest('[data-pet]'))return;const b=e.target.closest('[data-outdoor]');if(!b)return;const a=b.dataset.outdoor;if(a==='leave')return endOutdoor();if(a==='page'){if(visual?.turnPage()===false)return;readingPage=(readingPage+1)%3;renderReading();return}if(a==='tent'){if(cloud&&world!==actor)return toast('帐篷由主人搭建，你可以在已有的营地坐坐。');let w=state.worlds[world];w.camp=!w.camp;visual?.camp(w.camp);paired=false;if(w.camp)record(names[actor]+'在'+planets[world]+'搭起了帐篷','放好睡垫，点亮一盏露营灯。',{target:world,shared:world!==actor});save();renderCamp();return}if(a==='rest'){visual?.rest(paired);if(!campEvent)campEvent=record(names[actor]+'在帐篷前坐了一会儿','慢下来，听听周围的风。');renderCamp();return}if(a==='pair'){if(cloud)return toast('这里暂时只支持异步互访，实时并坐还没有开放。');paired=!paired;if(outdoorMode==='read'){visual?.sit(paired,true);if(paired&&readingEvent){readingEvent.shared=true;readingEvent.target=1-actor;readingEvent.title='我们一起在长椅上读书';readingEvent.body='在《风路过的地方》里，读到同一阵晚风。（双人动作演示）';save()}renderReading()}else{visual?.rest(paired);if(paired&&!campEvent)campEvent=record('我们一起在帐篷前露营','毯子上有两个人的位置，灯为我们亮着。（双人动作演示）',{target:1-actor,shared:true});else if(paired&&campEvent){campEvent.shared=true;campEvent.target=1-actor;campEvent.title='我们一起在帐篷前露营';save()}renderCamp()}}});
$('#go-camp').onclick=()=>outdoors('camp');$('#go-read').onclick=()=>outdoors('read');


handlers['select-food']=b=>selectFood(b.dataset.id);handlers['select-meal']=b=>selectMeal(b.dataset.id);handlers['fridge-prev']=()=>{fridgePage--;fridge()};handlers['fridge-next']=()=>{fridgePage++;fridge()};handlers['cook-step']=advanceCooking;
for(const [from,to]of [['eat-model','eat-fridge'],['pack-model','pack'],['eat-meal-model','eat-meal']])handlers[from]=async b=>{const view=modelView,id=b.dataset.id;if(!view||b.disabled)return;b.disabled=true;await view.consume(id);if(modelView!==view)return;handlers[to]({dataset:{id}})};


function petName(){return world===0?'饼干':'栗子'}
function showPet(){close();outdoorMode='pet';dock('');$('.scene-wrap').classList.add('pet-active');renderPet()}
function renderPet(){const p=visual?.readState().pet,mode=p?.mode||'idle',busy=['throw','fetch','return','feed-approach','feeding'].includes(mode);dock('<div class="dock-heading"><span>♧ '+petName()+' · '+({walk:'陪你散步',throw:'玩具飞出去啦',fetch:'跑去捡玩具',return:'叼着玩具回来了',feeding:'正在吃饭','feed-approach':'跑向饭碗',home:'回门口休息'}[mode]||'摇着尾巴等你')+'</span><button data-outdoor="leave" aria-label="让小狗回家">×</button></div><p class="subtle">'+(mode==='walk'?'用方向键或屏幕箭头散步，小狗会沿着小路跟随。':'它平时在家门口休息。一起玩一会儿吧。')+'</p><div class="dock-actions">'+[['walk',mode==='walk'?'结束散步':'一起散步'],['ball','扔小球'],['disc','扔飞盘'],['feed','喂一碗饭']].map(([id,text])=>'<button data-pet="'+id+'" '+(busy?'disabled':'')+'>'+text+'</button>').join('')+'</div>')}
function petCompleted(action){const w=state.worlds[world];w.pet=w.pet||{feeds:0,games:0,walks:0};if(action==='pet-fed'){w.pet.feeds++;record(names[actor]+'给'+petName()+'喂了饭','小狗低下头，把碗里的饭吃干净了。',{target:world,shared:world!==actor})}else if(action.startsWith('pet-fetch-')){w.pet.games++;record(names[actor]+'和'+petName()+'玩了'+(action.endsWith('disc')?'飞盘':'小球'),'小狗跑过去，叼着玩具回到了身边。',{target:world,shared:world!==actor})}if(outdoorMode==='pet')renderPet()}
$('#go-pet').onclick=()=>{endOutdoor();close();if(inside){inside=false;visual?.enter(false);refresh()}visual?.request('puppy')};
$('#activity-dock').addEventListener('click',e=>{const b=e.target.closest('[data-pet]');if(!b||b.disabled)return;let a=b.dataset.pet;if(a==='walk'&&visual?.readState().pet.mode==='walk'){visual.pet('home');state.worlds[world].pet??={feeds:0,games:0,walks:0};state.worlds[world].pet.walks++;record(names[actor]+'带'+petName()+'出去散步','沿着星球的小路走了一会儿，再回家休息。',{target:world,shared:world!==actor});renderPet();return}if(!visual?.pet(a))return toast('让小狗先把这件事做完吧。');renderPet()});


function cloudSettings(){
 modal('settings','Echoo','账号与两颗星球',
 '<p>你好，'+esc(cloud.session.username)+'。这是'+names[actor]+'的'+planets[actor]+'。</p>'+
 '<div class="cloud-account-note">账号身份固定，存档保存在服务器。私人手账仅本人可读；配对后可访问彼此的院子、冰箱、餐桌和共同回忆。<br>当前为异步互访，每隔约 5 秒在空闲时同步。天气仍是手动演示，双人同时走动、并坐与共同做饭尚未开放。</div>'+
 (!cloud.session.secure?'<p class="cloud-warning">HTTP 试玩连接：请仅使用临时测试密码和测试记录。正式记录前请配置 HTTPS。</p>':'')+
 (cloud.paired?'<p>♡ 已配对：'+names[1-actor]+' · '+planets[1-actor]+'</p><div class="form-actions">'+btn('go-partner','去对方的星球',true)+btn('unpair','解除配对')+'</div>':
 '<p>尚未配对。两个人先各自注册账号，一人生成邀请码，另一人输入。</p><div class="form-actions">'+btn('make-invite','生成邀请码',true)+'</div><div id="cloud-invite"></div><form id="pair-form" class="cloud-account-form"><label for="pair-code">对方的邀请码</label><input id="pair-code" name="code" required maxlength="36" autocomplete="off" placeholder="粘贴 36 位邀请码"><button type="submit" class="pill primary">接受邀请，连接星球</button></form>')+

 (cloud.session.registration?.canManage&&!cloud.session.registration.full?'<form id="join-code-form" class="cloud-account-form"><label for="join-code">设置新的加入口令</label><input id="join-code" name="code" required pattern="[a-zA-Z0-9]{6,24}" minlength="6" maxlength="24" autocomplete="off" placeholder="自己设置，6–24 位字母或数字"><p class="subtle">把口令告诉对方，用来注册第二个账号。保存后旧口令就失效。</p><button type="submit" class="pill">保存加入口令</button><p id="join-code-result" role="status"></p></form>':'')+
 '<div class="form-actions">'+btn('export-all','导出手账')+btn('logout','退出登录')+'</div>');
 const join=$('#join-code-form');if(join)join.onsubmit=async e=>{e.preventDefault();const b=join.querySelector('button');b.disabled=true;const result=await cloud.setJoinCode(join.elements.code.value);b.disabled=false;if(result){$('#join-code-result').textContent='已保存。把刚设置的口令告诉对方，就可以注册了。';join.reset()}};
 const form=$('#pair-form');if(form)form.onsubmit=e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;cloud.pair(form.elements.code.value.trim()).finally(()=>b.disabled=false)};
}
if(cloud){
 $('.identity small').textContent='账号与配对';
 handlers['make-invite']=async b=>{b.disabled=true;const result=await cloud.invite();b.disabled=false;if(!result||!$('#cloud-invite'))return;$('#cloud-invite').innerHTML='<div class="cloud-code">'+esc(result.code)+'</div><p class="subtle">24 小时内有效，只能使用一次。生成新码会让旧码失效。请私下发给对方。</p>'};
 handlers['go-partner']=()=>go(1-actor);
 handlers.unpair=()=>modal('unpair','YOUR OWN SPACE','解除配对？','<p>双方将无法继续互访，也看不到对方的记录。各自的存档仍保留；重新配对后，共同内容会再次显示。</p><div class="form-actions">'+btn('account','保留配对')+btn('confirm-unpair','解除配对')+'</div>');
 handlers.account=cloudSettings;
 handlers['confirm-unpair']=()=>cloud.unpair();
 handlers.logout=()=>cloud.logout();
 cloud.attach({
  getState:()=>state,
  apply:(next,remote)=>{if(remote){state=next;if(!cloud.paired&&world!==actor)go(actor);else refresh()}},
  canRefresh:()=>!currentPanel&&!outdoorMode,
  toast,settings:cloudSettings
 });
}

function bedroom(){
 modal('bed','SWEET DREAMS','把疲惫，交给柔软的床','<p class="subtle">枕头蓬松，被子刚刚铺好。在'+(world===actor?'自己的':names[world]+'的')+'小屋休息一会儿吧。</p><div class="form-actions">'+btn('sleep-now','躺下休息')+btn('write','写一页睡前手账')+'</div>');
}
handlers.stairs=()=>{endOutdoor();close();visual?.request('stairs')};
handlers.bed=()=>{endOutdoor();close();visual?.request('bed')};
handlers['sleep-now']=()=>{
 close();if(!visual?.sleep())return;outdoorMode='sleep';
 record(names[actor]+'在'+(world===actor?'自己的':names[world]+'的')+'小屋休息了一会儿','走上二层，钻进柔软的被子。把今天的疲惫慢慢放下。',{target:world,shared:world!==actor});
 dock('<div class="dock-heading"><span>☾ 在二层卧室休息</span><button data-outdoor="leave" aria-label="起床">×</button></div><p class="subtle">窗外的天气慢慢变化，这里有一床温暖的被子。</p><div class="dock-actions"><button data-outdoor="leave">起床，继续逛逛</button></div>');
};
